/**
 * I-only (imagery-only single-task) trial — design §4 row 3, §5.
 *
 * Sequence:
 *   1. Trial-start gate (empty circle + "press both arrow keys to start
 *      the next trial" hint, no arrow). The trial does not begin until
 *      the participant presses both arrow keys; never auto-passes.
 *   2. Rotation cue (2000 ms): centre-screen arrow showing the angle the
 *      grid will rotate to, so the participant can pre-imagine the
 *      rotated pattern. Mounted only AFTER the gate fires, so the arrow
 *      presentation is unambiguously part of the trial.
 *   3. Imagination period (5000 ms, 2026-05-08 design lock): empty circle
 *      with no arrow. Fixed-duration window in which the participant
 *      pre-imagines the rotated pattern; no input is accepted.
 *   4. Encoding node (one jsPsych trial spanning the whole imagery sequence,
 *      driven by an async on_load schedule so the grid frame mounts once
 *      and we avoid between-event flicker):
 *        a. Mount frame at rotation = 0°.
 *        b. Animate rotation 0 → rotation_deg over 500 ms via SVG transform.
 *        c. Stabilisation 1000 ms with the rotated grid visible.
 *        d. For each slot in the trial's 6-event {M, S} sequence:
 *             S-slot → star at the assigned cell, visible for 3000 ms,
 *                      then a 500 ms empty-circle offset. Listen for
 *                      ArrowRight/ArrowLeft. Recolour star green/red
 *                      synchronously on keypress (no latency).
 *             M-slot → invisible open-square placeholder at a non-star
 *                      cell, occupying 1000 ms + a 500 ms empty-circle
 *                      offset (the dot M-slot envelope). Same filler
 *                      primitive used by D-only / T-only S-slots, but
 *                      shorter: in I-only the placeholder stands in for
 *                      the dual-task condition's *memory item* (dot in
 *                      I+D, tone in I+T), not for its star, so it must
 *                      run on the M-slot envelope rather than the
 *                      S-slot envelope. Rendered invisibly so it does
 *                      not compete visually with the star events; its
 *                      sole purpose is the temporal envelope that keeps
 *                      single-task durations matched to dual-task ones.
 *        e. Tear down stars and dummies; restore fixation.
 *   3. ITI (800 ms blank with central fixation).
 *
 * No retention or recognition probe — the I-only trial ends after the last
 * star slot (per design §4 final paragraph).
 *
 * Per-star data rows are emitted via `jsPsych.data.write({...})` so each
 * star produces an `i_only_star` row alongside the surrounding nodes. This
 * matches the per-probe row shape from D-only / T-only and makes the
 * Step-10 data uploader trivially uniform across conditions.
 */
import htmlKeyboardResponse from '@jspsych/plugin-html-keyboard-response';

import { createGridFrame, setRotation } from '../visuals/frame.js';
import { addStar, recolourStar } from '../visuals/star.js';
import { addOpenSquare } from '../visuals/dummy.js';
import { removeElement } from '../visuals/dot.js';
import {
  sleep,
  stampTrialData,
  arrowCueNode,
  imaginationNode,
  trialStartGateNode,
  judgeStarResponse,
  itiNode,
  M_SLOT_MS,
  S_SLOT_MS,
  DOT_VISIBLE_MS,
  STAR_DURATION_MS,
  POST_STIMULUS_OFFSET_MS,
  ROTATION_ANIMATION_MS,
  POST_ROTATION_MS,
  FEEDBACK_COLOR_CORRECT,
  FEEDBACK_COLOR_WRONG,
  emitAuxDataRow,
  KEY_ON,
  KEY_OFF,
} from './shared.js';

/* I-only dummies sit in M-slots — the slot positions that the matched
 * dual-task conditions (I+D, I+T) use for memory items (dots / tones).
 * They therefore inherit the M-slot envelope (1000 ms visible onset +
 * 500 ms empty-circle offset = 1500 ms total), NOT the S-slot envelope
 * used by D-only / T-only dummies (which stand in for the *star* of
 * their matched dual-task condition). With this rule applied, every
 * single-task trial's encoding window is byte-identical to the matched
 * dual-task encoding window: I-only = 3×S_SLOT_MS + 3×M_SLOT_MS = 15 s,
 * matching I+D and I+T. The dummy is rendered invisibly either way, so
 * the only participant-visible effect of this lock is that the gap
 * between consecutive stars in I-only now matches the gap between
 * consecutive stars in I+D / I+T (one M-slot worth of waiting), instead
 * of being 2 s longer. */
const DUMMY_VISIBLE_LOCAL_MS = DOT_VISIBLE_MS; /* 1000 */
const DUMMY_SLOT_MS = M_SLOT_MS; /* 1500 = 1000 visible + 500 offset */
const ENCODING_TOTAL_MS =
  ROTATION_ANIMATION_MS + POST_ROTATION_MS + 3 * S_SLOT_MS + 3 * DUMMY_SLOT_MS;

/**
 * Trial preamble for imagery trials (gate-first revision — 2026-05-08):
 *   1. `trialStartGateNode` — empty circle (bull's-eye visible, no
 *      arrow). The participant presses both arrow keys to start the
 *      trial; the gate never auto-passes.
 *   2. `arrowCueNode` — rotation arrow over the empty grid for 2000 ms,
 *      no input. The arrow is the same `arrow.png` asset as the round-1
 *      reference, sized to 100 px and centred at the bull's-eye (not
 *      contained inside the central cell). It renders only after the
 *      gate fires, so the arrow presentation is unambiguously part of
 *      the started trial.
 *   3. `imaginationNode` — empty circle (no arrow) for a fixed 5000 ms.
 *      The participant uses this window to pre-imagine the rotated
 *      pattern. No input is accepted; the duration is fixed across
 *      trials so encoding-onset is consistent.
 *
 * The gate's `showArrow` / `rotation_deg` fields are kept on the data
 * row for analytic tagging only — they no longer drive any visual
 * rendering inside the gate.
 */
function gatePreambleNodes(params) {
  return [
    trialStartGateNode({
      trial_index_in_block: params.trial_index_in_block,
      showArrow: true,
      rotation_deg: params.rotation_deg,
      phase: 'i_only_trial_start',
      background_shade: params.background_shade,
      data: {
        rotation_deg: params.rotation_deg,
        background_shade: params.background_shade,
      },
    }),
    arrowCueNode({
      trial_index_in_block: params.trial_index_in_block,
      rotation_deg: params.rotation_deg,
      phase: 'i_only_arrow_cue',
      background_shade: params.background_shade,
      data: { background_shade: params.background_shade },
    }),
    imaginationNode({
      trial_index_in_block: params.trial_index_in_block,
      rotation_deg: params.rotation_deg,
      phase: 'i_only_imagination',
      background_shade: params.background_shade,
      data: { background_shade: params.background_shade },
    }),
  ];
}

/**
 * The encoding node — one jsPsych node spanning rotation animation,
 * stabilisation, and the 6-slot {M, S} sequence. We drive timing via
 * `setTimeout` / `await sleep(...)` from `on_load` so the grid frame stays
 * mounted across all events (no flicker). The ENCODING_TOTAL_MS constant
 * gives jsPsych a hard upper bound; the schedule completes earlier and the
 * trial ends naturally at trial_duration.
 */
function encodingNode(params) {
  const slot_onsets_ts_ms = new Array(params.sequence.length).fill(null);
  return {
    type: htmlKeyboardResponse,
    stimulus: `<div id="i-only-mount" style="margin: 0 auto;"></div>`,
    choices: 'NO_KEYS',
    trial_duration: ENCODING_TOTAL_MS,
    on_load: () => {
      const mount = document.getElementById('i-only-mount');
      const frame = createGridFrame({
        rotation_deg: 0,
        fixation: '',
        background_shade: params.background_shade,
      });
      mount.appendChild(frame.wrapper);
      stampTrialData('encoding_onset_ts_ms', performance.now());

      void runImagerySchedule(frame, params, slot_onsets_ts_ms).catch((err) => {
        console.error('[i_only] encoding error', err);
      });
    },
    data: {
      phase: 'i_only_encoding',
      trial_index_in_block: params.trial_index_in_block,
      rotation_deg: params.rotation_deg,
      background_shade: params.background_shade,
      sequence: params.sequence.join(''),
      stars: params.stars.map((s) => ({
        slot: s.slot_index_in_seq,
        cell: s.cell,
        pattern_label: s.pattern_label,
      })),
      dummies: params.dummies.map((d) => ({
        slot: d.slot_index_in_seq,
        cell: d.cell,
      })),
      slot_onsets_ts_ms,
    },
  };
}

async function runImagerySchedule(frame, params, slot_onsets_ts_ms) {
  /* Animate rotation 0 → rotation_deg. CSS transition on the SVG transform
   * is the most reliable cross-browser approach; we apply it to the rotor
   * directly via inline transition + a re-set transform. */
  frame.rotor.style.transition = `transform ${ROTATION_ANIMATION_MS}ms ease-in-out`;
  /* Force one frame so the transition picks up the change, then set the
   * target rotation. */
  await sleep(0);
  setRotation(frame, params.rotation_deg);
  await sleep(ROTATION_ANIMATION_MS);
  frame.rotor.style.transition = '';

  /* Stabilisation. */
  await sleep(POST_ROTATION_MS);

  /* Plan the per-slot events. */
  const eventBySlot = new Map();
  for (const s of params.stars) eventBySlot.set(s.slot_index_in_seq, { kind: 'S', star: s });
  for (const d of params.dummies) eventBySlot.set(d.slot_index_in_seq, { kind: 'M', dummy: d });

  for (let slotIdx = 0; slotIdx < params.sequence.length; slotIdx++) {
    const ev = eventBySlot.get(slotIdx);
    if (!ev) continue;
    slot_onsets_ts_ms[slotIdx] = Math.round(performance.now());
    if (ev.kind === 'S') {
      await runStarSlot(frame, params, ev.star);
    } else {
      await runDummySlot(frame, ev.dummy);
    }
  }
}

/**
 * Run one star slot: render the star, listen for the first valid response
 * (ArrowRight = on-pattern, ArrowLeft = off-pattern), recolour the star
 * green/red SYNCHRONOUSLY on the keypress (2026-05-08 design lock — the
 * prior 600 ms feedback latency was retired because pilot participants
 * read the gap as "the program took a while to register my answer"). The
 * star then clears at the end of the 3000 ms visible onset, followed by
 * the shared 500 ms empty-circle offset. Skipped stars get no feedback
 * (design lock — see the inline note below). Per-star data is written
 * to the global jsPsych data store as a separate row.
 */
async function runStarSlot(frame, params, star) {
  const starEl = addStar(frame, star.cell);
  const starOnsetTs = performance.now();

  let responded = false;
  let said_on = null;
  let response_key = null;
  let response_rt_ms = null;
  let feedback_correct = null;
  let feedback_shown_at_ms = null;

  /* Capture the FIRST valid keypress; ignore subsequent ones. We use the
   * window keydown listener (capture phase) so the listener catches the
   * event even if jsPsych's display element is focused elsewhere.
   * Auto-repeat events (held keys) are dropped explicitly so a participant
   * resting a finger on Arrow doesn't replay the response. preventDefault
   * stops the browser scroll that arrow keys would otherwise trigger. */
  const keyHandler = (e) => {
    if (e.repeat) return;
    const k = e.key.toLowerCase();
    if (k !== KEY_ON && k !== KEY_OFF) return;
    e.preventDefault();
    e.stopPropagation();
    if (responded) return;
    responded = true;
    response_key = k;
    response_rt_ms = Math.round(performance.now() - starOnsetTs);
    const judged = judgeStarResponse(k, star.is_on_pattern);
    said_on = judged.said_on;
    feedback_correct = judged.correct;
    /* Recolour synchronously — green for correct, red for incorrect — on
     * the same frame as the keypress. `feedback_shown_at_ms` therefore
     * equals `response_rt_ms`. */
    const colour = feedback_correct ? FEEDBACK_COLOR_CORRECT : FEEDBACK_COLOR_WRONG;
    recolourStar(starEl, colour);
    feedback_shown_at_ms = response_rt_ms;
  };
  window.addEventListener('keydown', keyHandler, { capture: true });

  /* Skipped stars (no response within the slot) get NO feedback — the
   * design lock removed the "no-response → red star" cue so an absent
   * response does not pull attention to itself. The star simply stays
   * white for its full duration and is then removed. */

  await sleep(STAR_DURATION_MS);

  /* Cleanup. */
  window.removeEventListener('keydown', keyHandler, { capture: true });
  removeElement(starEl);
  await sleep(POST_STIMULUS_OFFSET_MS);

  /* Emit a per-star data row. */
  emitAuxDataRow({
    phase: 'i_only_star',
    trial_index_in_block: params.trial_index_in_block,
    rotation_deg: params.rotation_deg,
    probe_position: star.probe_position,
    slot_index_in_seq: star.slot_index_in_seq,
    probed_cell: star.cell,
    pattern_label: star.pattern_label,
    is_on_pattern: star.is_on_pattern,
    responded,
    said_on,
    response_key,
    response_rt_ms,
    star_correct: feedback_correct === true,
    feedback_shown_at_ms,
    star_onset_ts_ms: Math.round(starOnsetTs),
  });
}

/**
 * Run one dummy (M-slot) event. The placeholder rect is mounted INVISIBLY
 * (`visible: false`) so the participant does not see it, but the slot still
 * occupies the M-slot envelope (1000 ms visible + 500 ms empty-circle
 * offset = 1500 ms total) — the same envelope a dot occupies in I+D and a
 * tone in I+T, because in I-only the dummy is the place-holder for the
 * matched dual-task's *memory item*, not its star. The visible/offset
 * split is preserved structurally (mirrors D-only and T-only's
 * `runEncodingSchedule`) so the schedule's `addOpenSquare` →
 * `removeElement` round-trip matches the dot/tone path beat-for-beat,
 * even though no on-screen change is visible to the participant.
 */
async function runDummySlot(frame, dummy) {
  const el = addOpenSquare(frame, dummy.cell, { visible: false });
  await sleep(DUMMY_VISIBLE_LOCAL_MS);
  removeElement(el);
  await sleep(DUMMY_SLOT_MS - DUMMY_VISIBLE_LOCAL_MS);
}

/**
 * Compose all jsPsych nodes for one I-only trial.
 *
 * I-only has no retention/maintenance phase — the trial ends after the last
 * star slot — so the ITI is rendered with a blank fixation. The persistent
 * '?' glyph is reserved for conditions that hold items in mind across a
 * retention window (D-only, T-only, I+D, I+T); showing it after a star-only
 * trial would imply an upcoming probe that never comes. Mirrors the round-1
 * `cond_ii1.html` reference, which also leaves the centre blank between
 * star-only trials.
 */
export function iOnlyTrial(params) {
  return [
    ...gatePreambleNodes(params),
    encodingNode(params),
    itiNode({ phase: 'i_only_iti', fixation: '', background_shade: params.background_shade }),
  ];
}
