/**
 * I+D (imagery + dots) dual-task trial — design §4 row 4, §5–6.
 *
 * Sequence:
 *   1. Trial-start gate (empty circle + "press both arrow keys to start
 *      the next trial" hint, no arrow). The trial does not begin until
 *      the participant presses both arrow keys; never auto-passes.
 *   2. Rotation cue (2000 ms): centre-screen arrow showing the required
 *      turn of the frame. Mounted only AFTER the gate fires, so the
 *      arrow presentation is unambiguously part of the trial.
 *   3. Imagination period (5000 ms, 2026-05-08 design lock): empty circle
 *      with no arrow. Fixed-duration window in which the participant
 *      pre-imagines the rotated pattern; no input is accepted.
 *   4. Encoding node (single jsPsych trial; async on_load schedule so the
 *      grid frame mounts once and we avoid between-event flicker):
 *        a. Mount frame at rotation = 0°.
 *        b. Animate rotation 0 → rotation_deg over 500 ms.
 *        c. Stabilisation 1000 ms with the rotated grid visible.
 *        d. For each slot in the 6-event memory/star sequence:
 *             M-slot → white dot at the assigned cell, 1000 ms visible,
 *                      500 ms blank (= 1500 ms total).
 *             S-slot → star at the assigned cell, visible for 3000 ms,
 *                      then a 500 ms empty-circle offset. Listen for
 *                      ArrowRight/ArrowLeft. Answered stars recolour
 *                      green/red SYNCHRONOUSLY on keypress (2026-05-08
 *                      design lock — the prior 600 ms feedback latency
 *                      was retired). Skipped stars receive no feedback.
 *        e. Tear down stimuli; restore fixation.
 *   5. Retention 2000 ms with central question mark.
 *   6. Three recognition probes in the precomputed probe order. Probe type
 *      balance is enforced across the block, not fixed within each trial.
 *      Each probe: a single
 *      dot at the probed cell on a non-rotated frame, shown for a fixed
 *      3000 ms response window. Answered probes recolour on the still-
 *      visible dot and stay on screen until the 3000 ms onset ends; a
 *      500 ms question-mark-only offset then hands directly to the next
 *      probe (probes run back-to-back).
 *   7. Final ITI 800 ms.
 *
 * Per-star data rows are emitted via `jsPsych.data.write({...})` so each
 * star produces an `i_d_star` row alongside the encoding node. Probe data
 * is captured on the probe nodes (`i_d_probe` phase) — both stream into the
 * Step-10 uploader uniformly.
 */
import htmlKeyboardResponse from '@jspsych/plugin-html-keyboard-response';

import { createGridFrame, clearStimuli, setFixation, setRotation } from '../visuals/frame.js';
import { addDot, removeElement } from '../visuals/dot.js';
import { addStar, recolourStar } from '../visuals/star.js';
import {
  sleep,
  stampTrialData,
  arrowCueNode,
  imaginationNode,
  trialStartGateNode,
  timedResponseWindowNode,
  frameNode,
  judgeProbeResponse,
  judgeStarResponse,
  itiNode,
  M_SLOT_MS,
  S_SLOT_MS,
  DOT_VISIBLE_MS,
  STAR_DURATION_MS,
  POST_STIMULUS_OFFSET_MS,
  RETENTION_MS,
  PROBE_RESPONSE_MS,
  PROBE_OFFSET_MS,
  ROTATION_ANIMATION_MS,
  POST_ROTATION_MS,
  FEEDBACK_COLOR_CORRECT,
  FEEDBACK_COLOR_WRONG,
  emitAuxDataRow,
  KEY_YES,
  KEY_NO,
  KEY_ON,
  KEY_OFF,
} from './shared.js';

const ENCODING_TOTAL_MS = ROTATION_ANIMATION_MS + POST_ROTATION_MS + 3 * M_SLOT_MS + 3 * S_SLOT_MS;

/**
 * Trial preamble for imagery + dot trials — see
 * `i_only.js#gatePreambleNodes` for the full rationale of the
 * empty-circle gate → both-arrow-keys → rotation-cue → imagination flow.
 */
function gatePreambleNodes(params) {
  return [
    trialStartGateNode({
      trial_index_in_block: params.trial_index_in_block,
      showArrow: true,
      rotation_deg: params.rotation_deg,
      phase: 'i_d_trial_start',
      background_shade: params.background_shade,
      data: {
        rotation_deg: params.rotation_deg,
        background_shade: params.background_shade,
      },
    }),
    arrowCueNode({
      trial_index_in_block: params.trial_index_in_block,
      rotation_deg: params.rotation_deg,
      phase: 'i_d_arrow_cue',
      background_shade: params.background_shade,
      data: { background_shade: params.background_shade },
    }),
    imaginationNode({
      trial_index_in_block: params.trial_index_in_block,
      rotation_deg: params.rotation_deg,
      phase: 'i_d_imagination',
      background_shade: params.background_shade,
      data: { background_shade: params.background_shade },
    }),
  ];
}

function encodingNode(params) {
  const slot_onsets_ts_ms = new Array(params.sequence.length).fill(null);
  return {
    type: htmlKeyboardResponse,
    stimulus: `<div id="i-d-mount" style="margin: 0 auto;"></div>`,
    choices: 'NO_KEYS',
    trial_duration: ENCODING_TOTAL_MS,
    on_load: () => {
      const mount = document.getElementById('i-d-mount');
      const frame = createGridFrame({
        rotation_deg: 0,
        fixation: '',
        background_shade: params.background_shade,
      });
      mount.appendChild(frame.wrapper);
      stampTrialData('encoding_onset_ts_ms', performance.now());

      void runEncodingSchedule(frame, params, slot_onsets_ts_ms).catch((err) => {
        console.error('[i_d] encoding error', err);
      });
    },
    data: {
      phase: 'i_d_encoding',
      trial_index_in_block: params.trial_index_in_block,
      rotation_deg: params.rotation_deg,
      background_shade: params.background_shade,
      sequence: params.sequence.join(''),
      memory_items: params.memory_items.map((m) => ({
        slot: m.slot_index_in_seq,
        encoding_position: m.encoding_position,
        cell: m.cell,
        pattern_label: m.pattern_label,
      })),
      stars: params.stars.map((s) => ({
        slot: s.slot_index_in_seq,
        cell: s.cell,
        pattern_label: s.pattern_label,
      })),
      slot_onsets_ts_ms,
    },
  };
}

async function runEncodingSchedule(frame, params, slot_onsets_ts_ms) {
  /* Animate rotation 0 → rotation_deg via CSS transition on the rotor. */
  frame.rotor.style.transition = `transform ${ROTATION_ANIMATION_MS}ms ease-in-out`;
  await sleep(0);
  setRotation(frame, params.rotation_deg);
  await sleep(ROTATION_ANIMATION_MS);
  frame.rotor.style.transition = '';

  /* Stabilisation. */
  await sleep(POST_ROTATION_MS);

  const eventBySlot = new Map();
  for (const m of params.memory_items) eventBySlot.set(m.slot_index_in_seq, { kind: 'M', item: m });
  for (const s of params.stars) eventBySlot.set(s.slot_index_in_seq, { kind: 'S', star: s });

  for (let slotIdx = 0; slotIdx < params.sequence.length; slotIdx++) {
    const ev = eventBySlot.get(slotIdx);
    if (!ev) continue;
    slot_onsets_ts_ms[slotIdx] = Math.round(performance.now());
    if (ev.kind === 'M') {
      const dot = addDot(frame, ev.item.cell);
      await sleep(DOT_VISIBLE_MS);
      removeElement(dot);
      await sleep(M_SLOT_MS - DOT_VISIBLE_MS);
    } else {
      await runStarSlot(frame, params, ev.star);
    }
  }

  clearStimuli(frame);
  setFixation(frame, '');
}

async function runStarSlot(frame, params, star) {
  const starEl = addStar(frame, star.cell);
  const starOnsetTs = performance.now();

  let responded = false;
  let said_on = null;
  let response_key = null;
  let response_rt_ms = null;
  let feedback_correct = null;
  let feedback_shown_at_ms = null;

  const keyHandler = (e) => {
    if (e.repeat) return;
    const k = e.key.toLowerCase();
    if (k !== KEY_ON && k !== KEY_OFF) return;
    e.preventDefault();
    e.stopPropagation();
    if (responded) return;
    responded = true;
    response_key = k;
    response_rt_ms = Math.round(performance.now() - starOnsetTs);
    const judged = judgeStarResponse(k, star.is_on_pattern);
    said_on = judged.said_on;
    feedback_correct = judged.correct;
    /* Recolour synchronously — green for correct, red for incorrect — on
     * the same frame as the keypress (2026-05-08 design lock; the prior
     * 600 ms latency was retired). `feedback_shown_at_ms` therefore
     * equals `response_rt_ms`. */
    const colour = feedback_correct ? FEEDBACK_COLOR_CORRECT : FEEDBACK_COLOR_WRONG;
    recolourStar(starEl, colour);
    feedback_shown_at_ms = response_rt_ms;
  };
  window.addEventListener('keydown', keyHandler, { capture: true });

  /* Skipped stars get NO feedback (design lock — see i_only.js). */

  await sleep(STAR_DURATION_MS);

  window.removeEventListener('keydown', keyHandler, { capture: true });
  removeElement(starEl);
  await sleep(POST_STIMULUS_OFFSET_MS);

  emitAuxDataRow({
    phase: 'i_d_star',
    trial_index_in_block: params.trial_index_in_block,
    rotation_deg: params.rotation_deg,
    probe_position: star.probe_position,
    slot_index_in_seq: star.slot_index_in_seq,
    probed_cell: star.cell,
    pattern_label: star.pattern_label,
    is_on_pattern: star.is_on_pattern,
    responded,
    said_on,
    response_key,
    response_rt_ms,
    star_correct: feedback_correct === true,
    feedback_shown_at_ms,
    star_onset_ts_ms: Math.round(starOnsetTs),
  });
}

function retentionNode(params) {
  return frameNode({
    mount_id: 'i-d-retention-mount',
    phase: 'i_d_retention',
    trial_duration: RETENTION_MS,
    fixation: '?',
    background_shade: params.background_shade,
    timestamp_field: 'retention_onset_ts_ms',
    data: {
      trial_index_in_block: params.trial_index_in_block,
      background_shade: params.background_shade,
    },
  });
}

function probeNode(params, probe) {
  return timedResponseWindowNode({
    mount_id: 'i-d-probe-mount',
    phase: 'i_d_probe',
    onset_ms: PROBE_RESPONSE_MS,
    offset_ms: PROBE_OFFSET_MS,
    fixation: '?',
    background_shade: params.background_shade,
    allowed_keys: [KEY_YES, KEY_NO],
    timestamp_field: 'probe_onset_ts_ms',
    data: {
      trial_index_in_block: params.trial_index_in_block,
      background_shade: params.background_shade,
    },
    on_load: (frame, state) => {
      state.probeDot = addDot(frame, probe.cell);
    },
    on_response: (_frame, state, key) => {
      const judged = judgeProbeResponse(key, probe.is_target);
      state.said_yes = judged.said_yes ?? null;
      state.probe_correct = judged.correct;
      const color = judged.correct ? FEEDBACK_COLOR_CORRECT : FEEDBACK_COLOR_WRONG;
      if (state.probeDot) state.probeDot.setAttribute('fill', color);
    },
    on_onset_end: (_frame, state) => {
      removeElement(state.probeDot);
      state.probeDot = null;
    },
    on_finish: (data, state) => {
      const judged = judgeProbeResponse(state.response_key, probe.is_target);
      data.probe_position = probe.probe_position;
      data.encoding_position = probe.encoding_position;
      data.probe_type = probe.type;
      data.probed_cell = probe.cell;
      data.probe_pattern_label = probe.pattern_label;
      data.is_target = probe.is_target;
      data.responded = judged.responded;
      data.said_yes = judged.said_yes ?? null;
      data.probe_correct = judged.correct;
    },
  });
}

/**
 * Compose all jsPsych nodes for one I+D trial.
 */
export function iDTrial(params) {
  const out = [...gatePreambleNodes(params), encodingNode(params), retentionNode(params)];
  for (const probe of params.probes) {
    out.push(probeNode(params, probe));
  }
  out.push(itiNode({ background_shade: params.background_shade }));
  return out;
}
